    result = invoke(app, service, 'reader', [('mode', 'read'), ('tag', 'one'), ('tag', 'two'), ('tag', 'one')])
    assert result == {'mode': 'read', 'tags': ['one', 'two', 'one']}
    service = r.X20Service()
